// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"blockchain":{"slug":"blockchain","cat":"basics","en":"Blockchain","contentLocale":"zh-Hans","term":"区块链（Blockchain）","aka":["Blockchain","分布式账本"],"short":"区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。","body":[["你可以把区块链想象成一本所有人都能查看的记账本。每隔一段时间，网络会把新发生的交易打包成一个“区块”，每个区块都记录着上一个区块的",["哈希值","transaction-hash"],"，于是一个接一个连成“链”。想改动旧记录，就必须重算之后所有区块，还要说服网络里的多数参与者接受，成本极高。"],["谁有权写入下一个区块，由共识机制决定。",["比特币","bitcoin"],"用",["工作量证明（PoW）","proof-of-work"],"，",["以太坊","ethereum"],"自 2022 年 9 月起改用",["权益证明（PoS）","proof-of-stake"],"。不同公链在出块速度、手续费和去中心化程度上取舍不同，这也是为什么同一笔转账在不同链上的到账时间和 ",["Gas 费","gas-fee"],"差别很大。"],"对普通用户来说，区块链最直接的意义是：链上转账公开可查，你可以用区块浏览器输入交易哈希确认是否到账；但链上交易一旦确认通常无法撤回，地址填错、网络选错，资产很难找回。"],"example":"假设你从交易所提 500 USDT 到自己的钱包。提币成功后，交易所会给你一串交易哈希（TxID）。你把它粘贴到对应链的区块浏览器里，能看到这笔交易被打包进第 1,000,000 号区块，之后又有 12 个新区块接在后面，也就是 12 个确认。确认数越多，这笔记录被推翻的可能性越低，很多交易所要求一定确认数后才给你入账。","mistakes":["以为区块链上的转账可以像银行一样申请撤回，实际上确认后基本无法回滚。","把“区块链”和“比特币”混为一谈，比特币只是第一个大规模应用区块链的项目。","提币时只看币种不看网络，例如把 ERC20 地址当成 TRC20 地址使用，导致资产无法到账。"],"faq":[{"q":"区块链和比特币是什么关系？","a":"比特币是运行在比特币区块链上的原生资产，区块链是它的底层记账技术。如今以太坊、Solana 等也都有各自的区块链。"},{"q":"区块链上的数据真的不能改吗？","a":"理论上可以，但需要掌握网络大部分算力或质押量并重写后续所有区块，在大型公链上成本极高，所以通常视为不可篡改。"},{"q":"区块链上的信息谁都能看到吗？","a":"公链上的地址、金额和交易记录都是公开的，但地址本身不直接显示真实身份。一旦地址和身份被关联，历史记录就都能被追溯。"}],"title":"什么是区块链？区块链的含义与工作原理","description":"用通俗的话讲清区块链是什么：区块如何串成链、共识机制的作用、链上转账为何公开可查却难以撤回，以及新手提币时要注意什么。","related":[["cryptocurrency","加密货币（Cryptocurrency）","加密货币是依靠密码学和区块链记账、无需银行等中心机构即可点对点转移的数字资产，比特币是第一个加密货币。"],["proof-of-work","工作量证明（PoW）","工作量证明（PoW）是一种共识机制，矿工通过大量计算竞争求解哈希难题，最先找到答案的人获得出块权和奖励，比特币采用这种机制。"],["proof-of-stake","权益证明（PoS）","权益证明（PoS）是一种共识机制，验证者通过质押代币获得出块和验证资格，作恶会被罚没质押，以太坊自 2022 年起采用。"],["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"],["block-explorer","区块浏览器（Block explorer）","区块浏览器是一种可以按交易哈希、钱包地址或区块高度查询区块链上公开记录的网站或工具，例如以太坊的Etherscan和波场的Tronscan。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"trading-volume":{"slug":"trading-volume","cat":"trading","en":"Trading volume","contentLocale":"zh-Hans","term":"成交量（Trading Volume）","aka":["交易量","24 小时成交量","trading volume"],"short":"成交量是在一段时间内实际成交的资产数量或金额，例如 24 小时成交量，用来衡量一个币或一个市场的交易活跃程度。","body":[["成交量既可以按币的数量计算（例如成交了 2,000 个 ",["ETH","ethereum"],"），也可以按计价金额计算（例如成交了 600 万 ",["USDT","usdt"],"）。行情网站常展示 24 小时成交量，K 线图下方的柱状图则显示每根 K 线时间段内的成交量。"],["交易者常把价格和成交量放在一起看：放量突破通常比缩量突破更可信，价格上涨但成交量持续萎缩，说明追高的人在减少。不过成交量只说明“有多少人在交易”，不说明方向，也不等于",["流动性","liquidity"],"好。"],["需要注意的是，现货成交量和合约成交量要分开看，合约因为有",["杠杆","leverage"],"，名义成交量往往远高于现货。另外，部分小",["交易所","centralized-exchange"],"存在",["刷量","wash-trading"],"，单一平台的数字可信度有限，参考多家主流交易所的数据更稳妥。"]],"example":"假设某币总市值 10 亿 USDT，24 小时成交量 2 亿 USDT，换手率约 20%，属于比较正常的活跃度。另一个币市值只有 2 亿 USDT，却显示 24 小时成交量 5 亿 USDT，换手率高达 250%，而订单簿每档只挂了几千 USDT。这种成交量和深度明显不匹配的情况，就值得怀疑存在刷量。","mistakes":["把成交量大直接理解为价格要涨，其实下跌时同样可以放量。","拿合约的名义成交量和现货成交量直接比较。","只看某一家小交易所公布的成交量，就认定这个币很热门。"],"faq":[{"q":"成交量放大是好事吗？","a":"成交量放大只说明交易变得活跃，要结合价格方向判断。放量上涨和放量下跌含义完全不同。"},{"q":"成交量和流动性一样吗？","a":"不一样。成交量是已经发生的交易，流动性是当前订单簿能承接多少交易。刷出来的成交量很高，但深度可能很薄。"}],"title":"成交量是什么？加密货币 24 小时交易量怎么看","description":"解释加密货币成交量（交易量）的含义、如何结合价格和 K 线解读放量缩量，以及如何识别刷量造成的虚高数据。","related":[["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["market-capitalization","市值（Market Cap）","市值是一个加密货币的当前价格乘以流通量得到的总价值，用来比较不同币种的规模，英文为 Market Cap。"],["open-interest","持仓量（Open Interest）","持仓量是某个合约市场中所有尚未平仓的合约总量，每一份多单都对应一份空单，它衡量的是有多少资金仍然留在市场里。"],["wash-trading","刷量（Wash Trading）","刷量是指同一方或串通的几方自己买卖自己的订单，制造虚假的成交量和活跃度，让一个币或一家交易所看起来比实际更热门。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"position-sizing":{"slug":"position-sizing","cat":"trading","en":"Position sizing","contentLocale":"zh-Hans","term":"仓位管理（Position Sizing）","aka":["仓位大小","头寸规模","position sizing"],"short":"仓位管理是根据账户总资金、可承受的单笔亏损和止损距离，计算每笔交易应该开多大仓位的方法，目的是让任何一笔交易都不会重伤账户。","body":["很多新手先决定“开多少倍”，再看能亏多少；正确顺序反过来：先决定这笔最多亏多少，再根据止损距离算出仓位大小。常见的做法是每笔风险控制在账户的 1% 到 2%。",["公式很简单：仓位价值 = 单笔可承受亏损 ÷ 止损距离（百分比）。止损越远，仓位就要越小；止损越近，仓位可以大一些。",["杠杆","leverage"],"只是决定你需要占用多少保证金，并不改变这笔交易的风险大小。"],["仓位管理还要考虑同时持有的多笔仓位。如果你同时做多五个高度相关的",["山寨币","altcoin"],"，每笔各亏 1%，一次普跌就可能同时触发，实际风险是 5%。"]],"example":["假设账户有 10,000 ",["USDT","usdt"],"，你决定单笔最多亏 1%，即 100 USDT。计划在 60,000 买入 ",["BTC","bitcoin"],"，止损 58,800，止损距离 2%。仓位价值 = 100 ÷ 2% = 5,000 USDT，约 0.0833 BTC。验证一下：0.0833 × 1,200 ≈ 100 USDT。如果用 5 倍杠杆，只需要占用 1,000 USDT 保证金，但触发止损时亏损依旧是 100 USDT。"],"mistakes":["先选杠杆倍数再决定仓位，没有计算止损时的实际亏损金额。","把止损设得很远却不缩小仓位，单笔亏损远超计划。","忽视多个相关仓位叠加后的整体风险。"],"faq":[{"q":"每笔交易应该用多少仓位？","a":"常见原则是每笔交易的最大亏损不超过账户的 1% 到 2%，再根据止损距离反推仓位大小。具体比例取决于你的策略和承受能力。"},{"q":"杠杆越高风险越大吗？","a":"风险大小由仓位价值和止损距离决定。但高杠杆让你更容易开出过大的仓位，强平价也更接近开仓价，所以实际操作中风险往往更大。"}],"title":"仓位管理是什么？每笔交易开多大仓位","description":"教你用账户资金、单笔风险和止损距离计算每笔交易合适的仓位大小，理解杠杆和风险的区别，避免一笔交易重伤账户。","related":[["risk-reward-ratio","盈亏比（Risk-Reward Ratio）","盈亏比是一笔交易计划中可能亏损的金额与可能盈利的金额之比，例如止损亏 100、止盈赚 300，就是 1:3 的盈亏比。"],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"先想能亏多少，再决定买多少"},"coin":null,"tool":null,"cta":false},"funding-rate":{"slug":"funding-rate","cat":"derivatives","en":"Funding rate","contentLocale":"zh-Hans","term":"资金费率（Funding Rate）","aka":["资金费","funding rate","funding fee"],"short":"资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。","body":[["资金费率通常由两部分组成：一部分是利率项，另一部分是溢价项，反映合约价格高于或低于",["指数价格","index-price"],"的程度。合约价格明显高于现货时，费率为正，多头付钱给空头，鼓励更多人开空；反之费率为负，空头付给多头。"],["资金费 = 仓位价值 × 资金费率，只在结算时刻向持仓的人收付。常见结算周期是每 8 小时一次，但部分",["交易所","centralized-exchange"],"和",["交易对","trading-pair"],"是 1、2 或 4 小时，极端行情时有的交易所还会临时调整周期或费率上下限，请以合约说明页面为准。"],"资金费率常被当作情绪指标：长期高正费率说明做多的人更多、愿意付溢价；深度负费率说明空头拥挤。资金费在用户之间互付，不是交易所收取的手续费，但对长期持仓的人来说是实实在在的成本或收益。"],"example":["假设你持有价值 20,000 ",["USDT","usdt"]," 的 ",["BTC","bitcoin"]," 多单，当期资金费率 +0.03%，8 小时结算一次。每次结算你需要支付 20,000 × 0.03% = 6 USDT，一天 18 USDT。如果第二天费率变成 −0.02%，空头反过来付钱给多头，你每次会收到 4 USDT。仓位价值按结算时的",["标记价格","mark-price"],"计算，所以价格变动后金额也会随之变化。"],"mistakes":["忽视长期高正费率的累积成本，持有多单数周后发现大部分利润被资金费吃掉。","为了赚资金费在结算前一刻开仓，却没考虑开平仓手续费和价格波动。","以为资金费率是交易所收的手续费，其实它在多空用户之间直接互付。"],"faq":[{"q":"资金费率为负是什么意思？","a":"负费率表示永续合约价格低于指数价格，空头需要付钱给多头。它说明当时做空的力量较强，但并不能单独预示价格方向。"},{"q":"资金费率多久结算一次？","a":"很多交易所默认每 8 小时一次，但部分交易对是 1、2 或 4 小时，具体以交易所合约详情页面显示为准。"},{"q":"不在结算时间持仓需要付资金费吗？","a":"不需要。只有在结算时刻持有仓位的用户才会收付资金费，结算前平仓则不涉及当期资金费。"}],"title":"什么是资金费率？永续合约资金费怎么算","description":"解释永续合约资金费率的含义、正负费率谁付给谁、资金费的计算公式和结算周期差异，以及如何把它当作市场情绪指标。","related":[["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["funding-rate-arbitrage","资金费率套利（Funding Rate Arbitrage）","资金费率套利是买入现货、同时在永续合约开等量空单，保持方向中性，赚取正资金费率期间空头收到的资金费的策略。"],["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。"],["index-price","指数价格（Index Price）","指数价格是交易所根据多家主流现货交易所的价格，按一定权重加权计算出的综合现货价格，用作标记价格和资金费率的基准。"],["open-interest","持仓量（Open Interest）","持仓量是某个合约市场中所有尚未平仓的合约总量，每一份多单都对应一份空单，它衡量的是有多少资金仍然留在市场里。"]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"没涨没跌也扣钱？带着成本完成最后一关"},"coin":null,"tool":"/funding-rates","cta":true},"defi":{"slug":"defi","cat":"defi","en":"DeFi (decentralized finance)","contentLocale":"zh-Hans","term":"DeFi（去中心化金融）","aka":["DeFi","去中心化金融","Decentralized finance"],"short":"DeFi（去中心化金融）是指运行在区块链智能合约上的金融服务，比如交易、借贷、质押和收益聚合，用户用自己的钱包直接参与，无需银行或交易所作为中介。","body":[["在 DeFi 里，规则写在",["智能合约","smart-contract"],"中并公开在链上。你连接自己的钱包，就能在 ",["DEX","dex"]," 上兑换代币、把资产存入",["借贷协议","defi-lending"],"赚利息、提供",["流动性","liquidity"],"赚手续费，资产在交易过程中不交给某个公司托管。代表性协议包括 Uniswap、Aave 等。"],["优点是开放和透明：任何人都能使用，资金流向可以链上查证，协议之间还能像乐高一样互相组合。缺点是风险更直接：合约漏洞、",["预言机","oracle"],"被操纵、",["跨链桥","cross-chain-bridge"],"被攻击、清算机制、恶意授权，出了问题通常没有客服和赔付。"],"使用 DeFi 还需要支付 Gas 费，在以太坊主网上小额操作可能不划算，很多用户会选择二层网络或其他费用较低的链。"],"example":"假设你把 1,000 USDC 存入一个借贷协议，当时显示的存款年化收益率为 4%。如果利率保持不变，一年后你约有 1,040 USDC。但利率是根据借款需求浮动的，实际可能更高或更低；如果协议合约被攻击，你的本金也可能受损，而存入和取出时每次还要付 Gas 费。","mistakes":["只看高收益率，不了解收益从哪里来、由什么风险支撑。","在以太坊主网用几十美元做 DeFi，Gas 费吃掉大部分收益。","连接钱包后对授权弹窗不加检查，给了陌生合约无限额度。"],"faq":[{"q":"DeFi 和 CeFi 有什么区别？","a":"CeFi 是中心化金融，如交易所理财，由公司托管资产；DeFi 由智能合约自动执行，你通过自托管钱包直接参与，自己承担操作和合约风险。"},{"q":"新手怎么开始接触 DeFi？","a":"先准备一个自托管钱包，用小额资金在知名协议上体验兑换或存款，同时学习 Gas 费、授权和无常损失等基本概念。"}],"title":"什么是 DeFi？去中心化金融的含义与风险","description":"DeFi 去中心化金融是什么意思？了解 DeFi 如何用智能合约提供交易、借贷和收益服务，与中心化平台的区别，以及新手需要知道的风险。","related":[["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。"],["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"],["total-value-locked","总锁仓价值（TVL）","总锁仓价值（TVL）是指存放在某个 DeFi 协议或某条公链智能合约中的资产总价值，通常以美元计算，用来衡量协议规模和资金规模。"],["defi-lending","DeFi 借贷","DeFi 借贷是通过智能合约进行的超额抵押借贷，存款人把资产存入资金池赚利息，借款人先存入抵押品再借出其他资产，抵押不足时会被自动清算。"],["liquidity-pool","流动性池（Liquidity Pool）","流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cross-chain-bridge":{"slug":"cross-chain-bridge","cat":"defi","en":"Cross-chain bridge","contentLocale":"zh-Hans","term":"跨链桥（Cross-chain Bridge）","aka":["跨链桥","桥","Bridge","跨链"],"short":"跨链桥是把资产或信息从一条区块链转移到另一条区块链的协议，常见方式是在源链锁定资产、在目标链铸造等量的映射代币。","body":[["不同",["区块链","blockchain"],"之间不能直接通信。跨链桥的典型做法是“锁定加铸造”：你在",["以太坊","ethereum"],"上把 1,000 ",["USDC","usdc"]," 存进桥的合约，桥在目标链上给你铸造 1,000 枚代表它的代币；反向操作时销毁目标链代币，再在源链释放原资产。也有桥使用两边的",["流动性池","liquidity-pool"],"直接兑换。"],["官方桥（如",["二层网络","layer-2"],"自带的桥）、第三方桥和",["交易所","centralized-exchange"],"充提都能实现跨链。交易所提币选择不同网络，本质上也是一种由平台承担的“跨链”，对新手来说往往更简单。"],"跨链桥锁着大量资产，是黑客重点攻击对象，历史上曾多次发生数亿美元规模的被盗事件。使用前确认官方入口、目标链地址和代币合约，并留意不同桥铸造的同名代币可能并不通用。"],"example":"假设你要把 1,000 USDC 从以太坊转到 Arbitrum。通过官方桥，你需要支付以太坊主网的 Gas 费，假设为 5 USDC，到账约 995 USDC。另一种做法是在已经持有 USDC 的交易所直接选择 Arbitrum 网络提币，假设手续费为 1 USDC，到账 999 USDC。两种方式的费用和到账时间都随网络状况变化，提交前以实际页面为准。","mistakes":["通过搜索结果或广告进入假的跨链桥网站。","跨完链才发现收到的是某个桥的映射币，目标交易所不支持充值。","在目标链上没有准备 Gas 代币，资产到账后无法转出。"],"faq":[{"q":"跨链桥安全吗？","a":"跨链桥历来是被攻击最多的 DeFi 类型之一，安全性取决于具体设计和运营方。尽量使用官方桥或经过长期检验的桥，并避免长期把大额资产放在桥接代币中。"},{"q":"跨链要多久？","a":"快的几分钟，慢的可能更久。例如部分 Optimistic 二层网络的官方桥从 L2 提回以太坊需要约 7 天挑战期。"}],"title":"什么是跨链桥？跨链转账原理与风险","description":"跨链桥是什么？了解锁定加铸造的跨链原理、官方桥与交易所跨网提币的区别、映射代币问题，以及使用跨链桥时的安全检查。","related":[["wrapped-token","封装代币（Wrapped Token）","封装代币是把一种资产按 1:1 比例在另一条链或另一种标准下表示出来的代币，例如 WBTC 让比特币能在以太坊上使用，WETH 把 ETH 变成 ERC20 格式。"],["layer-2","二层网络（Layer 2，L2）","二层网络（L2）是建立在一层区块链之上的扩容方案，在二层批量处理交易后把结果提交回主链，以更低的费用借用主链安全性。"],["blockchain-network","充提币网络（链的选择）","充提币网络是指充币或提币时选择的区块链，例如 USDT 可以走 TRC20、ERC20 或 BEP20 等不同网络，发送方和接收方必须选择同一条链。"],["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"转账之前，这几项一个也别猜"},"coin":null,"tool":null,"cta":false},"stablecoin":{"slug":"stablecoin","cat":"stablecoins","en":"Stablecoin","contentLocale":"zh-Hans","term":"稳定币（Stablecoin）","aka":["稳定币","Stablecoin","U","数字美元"],"short":"稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。","body":[["按支撑方式，稳定币大致分为三类：法币储备型，由发行方持有现金和短期国债等储备，如 Tether 发行的 ",["USDT","usdt"],"、Circle 发行的 ",["USDC","usdc"],"；加密资产抵押型，用超额加密资产抵押铸造，如 DAI；以及通过衍生品",["对冲","hedging"],"等机制维持价格的",["合成美元","synthetic-dollar"],"。2022 年 UST 崩盘说明，缺乏足够储备的算法型设计风险很大。"],["稳定币的价值依赖于储备的质量、透明度和赎回机制。市场恐慌或储备出问题时，价格可能偏离 1 美元，也就是",["脱锚","depeg"],"。"],["监管各国不同，例如欧盟 ",["MiCA","mica"]," 对稳定币发行方的规定自 2024 年 6 月 30 日起适用，部分交易所因此调整了对某些稳定币的支持。持有稳定币不等于持有银行存款，没有存款保险。"]],"example":"假设你在 BTC 价格 64,000 USDT 时卖出 0.5 BTC，得到 32,000 USDT，用来规避价格波动。只要 USDT 维持在 1 美元附近，这笔钱的美元价值基本不变。但如果某种稳定币短时间脱锚到 0.95 美元，你持有的 32,000 枚按市价就只值约 30,400 美元，差额 1,600 美元。","mistakes":["以为所有稳定币都一样安全，不看发行方和储备结构。","把稳定币当作有存款保险的银行存款。","充提稳定币时只看币种不看网络，选错链导致资产丢失。"],"faq":[{"q":"稳定币会脱锚吗？","a":"会。主流稳定币历史上也出现过短暂脱锚，算法稳定币还出现过彻底崩盘。分散持有、了解储备情况可以降低风险。"},{"q":"USDT 和 USDC 哪个好？","a":"两者都是法币储备型稳定币，区别在于发行方、储备披露方式、监管身份和各交易所的支持情况，可以根据用途和所在地规则选择。"}],"title":"什么是稳定币？稳定币的类型与脱锚风险","description":"稳定币是什么意思？了解法币储备型、加密抵押型和合成美元等稳定币类型，稳定币如何维持 1 美元，以及脱锚和监管差异。","related":[["usdt","USDT（泰达币）","USDT（泰达币）是由 Tether 公司发行、设计为与美元 1:1 挂钩的稳定币，也是市值和交易量最大的稳定币之一，大多数交易所的现货和合约都以它计价。"],["usdc","USDC（美元币）","USDC 是由 Circle 公司发行、与美元 1:1 挂钩的稳定币，储备主要为现金和短期美国国债，以储备披露较透明著称，在 DeFi 和合规场景中使用广泛。"],["depeg","脱锚（Depeg）","脱锚是指稳定币或锚定类资产的市场价格明显偏离它承诺跟随的价值，例如本应等于1美元的稳定币跌到0.95美元或涨到1.03美元。"],["crypto-backed-stablecoin","加密资产抵押型稳定币（Crypto-backed stablecoin）","加密资产抵押型稳定币是用户把ETH等加密资产超额抵押进智能合约后铸造出来的稳定币，DAI是最典型的例子，抵押品不足时仓位会被清算。"],["synthetic-dollar","合成美元（Synthetic dollar）","合成美元是一种通过持有现货加密资产、同时在永续合约上开等额空单实现Delta中性，从而让价值稳定在约1美元的稳定币，Ethena的USDe是代表。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT是美元吗？为什么买币常见它？"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false}});
